android {
    namespace "com.shopapp"
    defaultConfig {
        applicationId "com.shopapp"
        versionCode 42
    }
    signingConfigs {
        release {
            storeFile file(SHOPAPP_UPLOAD_STORE_FILE)
            storePassword SHOPAPP_UPLOAD_STORE_PASSWORD
            keyAlias SHOPAPP_UPLOAD_KEY_ALIAS
            keyPassword SHOPAPP_UPLOAD_KEY_PASSWORD
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.debug
        }
    }
}

apply plugin: "com.android.application"
apply plugin: "org.jetbrains.kotlin.android"
apply plugin: "com.facebook.react"

react {
    debuggableVariants = ["devDebug", "stagingDebug", "stagingRelease"]
    autolinkLibrariesWithApp()
}

android {
    namespace "com.shopapp"
    flavorDimensions "env"
    productFlavors {
        dev { applicationIdSuffix ".dev" }
        staging { applicationIdSuffix ".staging" }
        prod { }
    }
}
